def verify_membrane_status(bia_data, lab_data, 6ki_profile):
    if bia_data['phase_angle'] < 5.5 and lab_data['mda'] > 2.0:
        if 6ki_profile['cold_axis'] > 2.0:
            return {
                "status": "CRITICAL_METABOLIC_CRASH_MD2",
                "prohibited_methods": ["Zalmanov_Yellow_Baths", "Mechanical_Vibration_KiVI", "H2O2_Protocol"],
                "mandatory_methods": ["Prednisone_5mg_07AM", "Liposomal_Vitamin_E_800IE", "NAC_2400mg"]
            }
    if bia_data['phase_angle'] in range(5.5, 6.5) and lab_data['homa_ir'] > 2.5:
        if 6ki_profile['humidity_axis'] > 2.0:
            return {
                "status": "STAGNANT_STEROL_OVERLOAD_MA2",
                "prohibited_methods": ["Zalmanov_White_Emulsion", "IF_Fasting"],
                "mandatory_methods": ["Zalmanov_Yellow_Baths_41C", "KiVI_Vibration_7Hz", "Phosphatidylcholine_2.4g"]
            }
